}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-light .preview-card {
    background: #f8f9fa;
}

/* Dark theme */
.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
}

.preview-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-card {
    background: #313244;
    border-color: #45475a;
}

/* System theme */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
}

.preview-system .preview-header {
    background: rgba(108, 117, 125, 0.1);
}

.preview-system .preview-card {
    background: rgba(108, 117, 125, 0.08);
}

/* ── Responsive ── */

@@media (max-width: 768px) {
    .settings-container {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
